    virtual void v00();
    void*          m_lockVtable;                       // +0x04
    _RTL_CRITICAL_SECTION* Lock() { return reinterpret_cast<_RTL_CRITICAL_SECTION*>(m_lockSection); }
    unsigned char  m_lockSection[0x18];                // +0x08
    float          m_volume;                           // +0x20
    bool           m_crossfade;                        // +0x24
